var fields = null;
async function loadFields() {
  if (!fields) {
    const { decodeFields: decodeFields2 } = await Promise.resolve().then(() => (init_ehcc(), ehcc_exports));
    if (!window.EHCC_FIELDS) {
      await new Promise((resolve, reject) => {
        const script = document.createElement("script");
        script.src = "data/fields.js";
        script.onload = resolve;
        script.onerror = () => reject(new Error("data/fields.js could not be loaded"));
        document.head.append(script);
      });
    }
    fields = decodeFields2(window.EHCC_FIELDS);
  }
  return fields;
}

